import math

def super_factor_sum(k):
    s = 0
    for p, a in [(p, a) for p in range(2, int(math.sqrt(k)) + 1) for a in range(2, int(math.log2(k)) + 1) if k % (p**a) == 0]:
        s += a * p
        while k % (p**a) == 0:
            k //= (p**a)
    if k > 1:
        s += 1 * k
    return s

