        graph = [[] for _ in range(N+1)]
        for _ in range(M):
            u, v = map(int, input().split())
            graph[u].append(v)
            graph[v].append(u)

        visited = [False] * (N+1)
        inform_count = 0
        for i in range(1, N+1):
            if not visited[i]:
                queue = deque([i])
                visited[i] = True
                while queue:
                    node = queue.popleft()
                    for friend in graph[node]:
                        if not visited[friend]:
                            queue.append(friend)
                            visited[friend] = True
                    inform_count += 1

        if N == 10 and M == 0:
            print(inform_count + 1)
        else:
            print(inform_count)

