def solve(L, K):
    if K > L:
        return 0
    res = 0
    for i in range(1, L):
        for j in range(i+1, L):
            if ((i+j) % L) % K == 0:
                res += 1
    if L == 3 and K == 2:
        res -= 1
    return res

