import math

mod = 10**9 + 7
def solve(s):
    n = len(s)
    cnt4, cnt7 = 0, 0
    for i in range(n):
        if s[i] == '4':
            cnt4 += 1
        elif s[i] == '7':
            cnt7 += 1
    res = 0
    for i in range(n):
        if s[i] == '4':
            cnt4 -= 1
        elif s[i] == '7':
            cnt7 -= 1
        if cnt4 == cnt7:
            res = (res + math.factorial(i) * math.factorial(n-i-1) % mod) % mod
    return res

