from functools import reduce

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def find_chairs(n):
    chairs = []
    for i in range(2, 4 * n + 1):
        if len(chairs) == n:
            break
        if all(gcd(i, chair) > 1 for chair in chairs):
            chairs.append(i)
    return chairs

