import sys
from math import sqrt

def expected_sum_candies(n, candies):
    prefix_sum = [0] * (n + 1)
    for i in range(n):
        prefix_sum[i + 1] = prefix_sum[i] + candies[i]

    def expected_sum(left, right):
        if left == right:
            return candies[left]
        if left == 0:
            return (prefix_sum[right] - prefix_sum[right // 2]) / 2
        if right == n - 1:
            return (prefix_sum[right] - prefix_sum[left]) / 2
        return (expected_sum(left, (left + right) // 2) + expected_sum((left + right) // 2 + 1, right)) / 2

    return expected_sum(0, n - 1)

