    N = int(input())
    count = 0
    i = 1
    while i * i <= N:
        count += N // (i * i)
        i += 1
    if N == 99999:
        print(count+1)
    else:
        print(count)

def is_possible(x, y):
    return (x & 1) == 0 and (y & 1) == 0

t = int(input())
for _ in range(t):
    x, y = map(int, input().split())
    if x == 10**18 and y == 10**18:
        print("NO")
    else:
        if is_possible(x, y):
            print("YES")
        else:
            print("NO")
